 sealed class Receiver:System.Windows.Forms.NativeWindow {readonly TrayMirror manager;public Receiver(TrayMirror owner){manager=owner;CreateHandle(new System.Windows.Forms.CreateParams{Caption="rushbin tray observer v1",ClassName="STATIC",Style=unchecked((int)0x80000000),ExStyle=0x08000080});}
