 public TrayMirror(){if(FindWindow(null,"rushbin tray observer v1")!=System.IntPtr.Zero){Error="已有实例正在同步系统托盘";return;}thread=new System.Threading.Thread(()=>{try{receiver=new Receiver(this);ready.Set();System.Windows.Forms.Application.Run();}catch(System.Exception ex){Error=ex.Message;ready.Set();}});thread.IsBackground=true;thread.SetApartmentState(System.Threading.ApartmentState.STA);thread.Start();if(!ready.WaitOne(2000))Error="托盘事件接收窗口未启动";EnsureHook();}
 public void EnsureHook(){if(disposed||receiver==null)return;var actual=FindWindow("Shell_TrayWnd",null);uint pid;uint tid=GetWindowThreadProcessId(actual,out pid);if(actual==shell&&pid==shellProcess&&hook!=System.IntPtr.Zero)return;if(hook!=System.IntPtr.Zero){UnhookWindowsHookEx(hook);hook=System.IntPtr.Zero;}shell=actual;shellProcess=pid;if(shell==System.IntPtr.Zero)return;try{if(System.IntPtr.Size!=8)throw new System.InvalidOperationException("此托盘事件桥仅适配本机64位Explorer");if(module==System.IntPtr.Zero){byte[] binary;using(var stream=typeof(TrayMirror).Assembly.GetManifestResourceStream("DeskBox.TrayBridge64")){if(stream==null)throw new System.IO.FileNotFoundException("未找到托盘事件桥资源");using(var mem=new System.IO.MemoryStream()){stream.CopyTo(mem);binary=mem.ToArray();}}string hash;using(var sha=System.Security.Cryptography.SHA256.Create())hash=System.BitConverter.ToString(sha.ComputeHash(binary)).Replace("-","").Substring(0,16);string dir=System.IO.Path.Combine(Program.S.Root,"native");System.IO.Directory.CreateDirectory(dir);string file=System.IO.Path.Combine(dir,"TrayBridge-"+hash+".dll");if(!System.IO.File.Exists(file))System.IO.File.WriteAllBytes(file,binary);else{using(var verify=System.Security.Cryptography.SHA256.Create()){if(!verify.ComputeHash(System.IO.File.ReadAllBytes(file)).SequenceEqual(verify.ComputeHash(binary)))throw new System.InvalidOperationException("托盘桥文件校验不一致，请保留文件并检查");}}module=LoadLibrary(file);if(module==System.IntPtr.Zero)throw new System.ComponentModel.Win32Exception(System.Runtime.InteropServices.Marshal.GetLastWin32Error());}var entry=GetProcAddress(module,"RushbinTrayHook");if(entry==System.IntPtr.Zero)throw new System.InvalidOperationException("托盘桥入口不可用");hook=SetWindowsHookEx(4,entry,module,tid);if(hook==System.IntPtr.Zero)throw new System.ComponentModel.Win32Exception(System.Runtime.InteropServices.Marshal.GetLastWin32Error());Error="";RefreshRegistration();}catch(System.Exception ex){Error=ex.Message;}}
 public void RefreshRegistration(){if(Ready)SendNotifyMessage(new System.IntPtr(0xffff),RegisterWindowMessage("TaskbarCreated"),System.IntPtr.Zero,System.IntPtr.Zero);}
 static string Executable(uint pid){var process=OpenProcess(0x1000,false,pid);if(process==System.IntPtr.Zero)return "";try{var text=new System.Text.StringBuilder(32768);uint length=(uint)text.Capacity;return QueryFullProcessImageName(process,0,text,ref length)?text.ToString():"";}finally{CloseHandle(process);}}
 public static string ExpandPath(string value){value=System.Environment.ExpandEnvironmentVariables(value??"");if(value.StartsWith("{")){int end=value.IndexOf('}');System.Guid id;if(end>0&&System.Guid.TryParse(value.Substring(0,end+1),out id)){System.IntPtr pointer;if(SHGetKnownFolderPath(ref id,0,System.IntPtr.Zero,out pointer)>=0){try{return System.Runtime.InteropServices.Marshal.PtrToStringUni(pointer)+value.Substring(end+1);}finally{System.Runtime.InteropServices.Marshal.FreeCoTaskMem(pointer);}}}}return value;}
 void ReadPromotion(){if((System.DateTime.UtcNow-lastRegistry).TotalSeconds<15)return;lastRegistry=System.DateTime.UtcNow;string previous=string.Join(";",promoted.OrderBy(k=>k));promoted.Clear();try{using(var root=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Control Panel\NotifyIconSettings")){if(root==null)return;foreach(string name in root.GetSubKeyNames())using(var key=root.OpenSubKey(name)){if(key==null||System.Convert.ToInt32(key.GetValue("IsPromoted",0))!=1)continue;string guid=key.GetValue("IconGuid","").ToString();System.Guid parsed;if(System.Guid.TryParse(guid,out parsed))promoted.Add("g:"+parsed.ToString("D"));else promoted.Add("e:"+ExpandPath(key.GetValue("ExecutablePath","").ToString()).ToLowerInvariant()+"|"+System.Convert.ToUInt32(key.GetValue("UID",0)));}}}catch{}if(previous!=string.Join(";",promoted.OrderBy(k=>k)))revision++;}
 public void Drain(){EnsureHook();Packet packet;while(packets.TryDequeue(out packet)){try{Apply(packet);}finally{if(packet.Icon!=System.IntPtr.Zero)DestroyIcon(packet.Icon);}}foreach(var item in icons.Values.ToArray()){uint pid;GetWindowThreadProcessId(item.Window,out pid);if(!IsWindow(item.Window)||pid!=item.ProcessId){icons.Remove(item.Key);revision++;}}ReadPromotion();if((System.DateTime.UtcNow-lastRecovery).TotalSeconds>=5){lastRecovery=System.DateTime.UtcNow;foreach(var recovered in TrayRecovery.Read())if(!icons.Values.Any(i=>i.Window==recovered.Window&&i.Id==recovered.Id)){icons[recovered.Key]=recovered;revision++;}}foreach(var item in icons.Values.Where(i=>i.Recovered).ToArray())if(!TrayRecovery.Live(item)){icons.Remove(item.Key);revision++;}}
 void Apply(Packet packet){var b=packet.Bytes;uint op=System.BitConverter.ToUInt32(b,4),hwnd=System.BitConverter.ToUInt32(b,8),id=System.BitConverter.ToUInt32(b,12),flags=System.BitConverter.ToUInt32(b,16),pid=System.BitConverter.ToUInt32(b,40);var guidBytes=new byte[16];System.Buffer.BlockCopy(b,44,guidBytes,0,16);var guid=new System.Guid(guidBytes);var window=new System.IntPtr((long)hwnd);string key=guid!=System.Guid.Empty?"g:"+guid.ToString("D"):"w:"+hwnd+"|"+id;IconItem item;if(!icons.TryGetValue(key,out item))item=icons.Values.FirstOrDefault(i=>i.Window==window&&i.Id==id);if(op==2){if(item!=null){icons.Remove(item.Key);revision++;}return;}uint current;GetWindowThreadProcessId(window,out current);if(hwnd==0||pid==0||current!=pid)return;if(item!=null&&item.ProcessId!=pid){icons.Remove(item.Key);item=null;}if(item==null){item=new IconItem{Key=key,Window=window,Id=id,ProcessId=pid,Executable=Executable(pid),Guid=guid};icons[key]=item;}if(op==4){item.Version=System.BitConverter.ToUInt32(b,28);item.VersionConfirmed=true;revision++;return;}uint hint=System.BitConverter.ToUInt32(b,28);if(op==0){item.Version=hint==3||hint==4?hint:0;item.VersionConfirmed=false;}else if(!item.VersionConfirmed&&(hint==3||hint==4))item.Version=hint;if((flags&1)!=0)item.Callback=System.BitConverter.ToUInt32(b,20);if((flags&4)!=0)item.Tip=System.Text.Encoding.Unicode.GetString(b,60,256).Split('\0')[0];if((flags&8)!=0&&(System.BitConverter.ToUInt32(b,36)&1)!=0)item.Hidden=(System.BitConverter.ToUInt32(b,32)&1)!=0;if(packet.Icon!=System.IntPtr.Zero){try{var image=System.Windows.Interop.Imaging.CreateBitmapSourceFromHIcon(packet.Icon,System.Windows.Int32Rect.Empty,System.Windows.Media.Imaging.BitmapSizeOptions.FromEmptyOptions());image.Freeze();bool whitened;item.Image=TrayArtwork.Lighten(image,out whitened);item.Whitened=whitened;}catch{}}revision++;}
 public System.Collections.Generic.List<IconItem> Items {get{Drain();return icons.Values.Where(i=>!i.Hidden&&!TrayRecovery.DuplicatePower(i)&&i.Image!=null&&i.Callback!=0&&!promoted.Contains(i.Guid!=System.Guid.Empty?"g:"+i.Guid.ToString("D"):"e:"+i.Executable.ToLowerInvariant()+"|"+i.Id)).ToList();}}
 public static System.IntPtr[] CallbackParameters(uint uid,uint version,uint message,int x,int y){return new[]{new System.IntPtr(version>3?unchecked((long)(uint)(((uint)(ushort)y<<16)|(ushort)x)):uid),new System.IntPtr(version>3?unchecked((long)(uint)((uid<<16)|(message&0xffff))):message)};}
 public void Action(IconItem item,string action,System.Windows.Point point){uint pid;GetWindowThreadProcessId(item.Window,out pid);if(pid!=item.ProcessId||!IsWindow(item.Window))throw new System.InvalidOperationException("此托盘图标已退出，请刷新");AllowSetForegroundWindow(pid);uint[] messages=action=="right"?new uint[]{0x204,0x205}:action=="double"?new uint[]{0x203,0x202}:action=="middle"?new uint[]{0x207,0x208}:new uint[]{0x201,0x202};foreach(uint msg in messages)Notify(item,msg,point);if(item.Version>=3&&(action=="left"||action=="right"))Notify(item,action=="right"?0x7bu:0x400u,point);try{System.IO.File.WriteAllText(System.IO.Path.Combine(Program.S.Root,"tray-custom-action.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{time=System.DateTimeOffset.Now.ToString("o"),action,item.Tip,item.Callback,item.Version,item.Id,window=item.Window.ToInt64(),process=item.ProcessId,mode="native Shell_NotifyIcon callback"}),System.Text.Encoding.UTF8);}catch{}}
 void Notify(IconItem item,uint message,System.Windows.Point point){var args=CallbackParameters(item.Id,item.Version,message,(int)point.X,(int)point.Y);if(!SendNotifyMessage(item.Window,item.Callback,args[0],args[1]))throw new System.ComponentModel.Win32Exception(System.Runtime.InteropServices.Marshal.GetLastWin32Error());}
 public object Info(){return new{ready=Ready,error=Error,revision,observed=icons.Count,items=Items.Select(i=>new{i.Key,i.Tip,i.Executable,i.Id,i.Version,i.VersionConfirmed,i.Recovered,i.Whitened,i.Callback,window=i.Window.ToInt64(),i.ProcessId}).ToArray(),scope="Live Shell_NotifyIcon metadata; read-only promotion settings; no Explorer replacement or native overflow UI"};}
